import {escapeText as esc,icon} from './assets.js';
import {activityLabels,goalLabels,bmiReference,canPersonalize} from './health-profile.js';
import {dietAssessment} from './nutrition.js';
import {generalDietNote} from './nutrition-view.js';
export function profileSummary(state){const p=state.profile,bmi=bmiReference(p);return `<section class="profile-summary"><div class="profile-monogram" aria-hidden="true">${icon('book')}</div><div><strong>${p?'把喜欢，吃成日常':'先认识自己，再慢慢挑喜欢的'}</strong><p>${p?`${esc(goalLabels[p.goal])}${bmi?' · BMI '+bmi.value:' '}${canPersonalize(p)?' · 饮食建议已开启':' · 通用选餐模式'}`:'身高、体重和目标可选填写，饭本留在你的浏览器。'}</p></div><button class="text-button" data-action="open-profile">${p?'编辑资料':'填写资料'} ${icon('arrow')}</button></section>`;}
const options=(values,current)=>Object.entries(values).map(([key,label])=>`<option value="${key}" ${key===current?'selected':''}>${esc(label)}</option>`).join('');
export function profileMarkup(state,today){const p=state.profile??{},bmi=bmiReference(p);return `<section class="profile-editor"><div class="section-head"><div><h2>你的饮食参考档案</h2><p>都可以留空，也可以随时清除。</p></div><span class="local-badge">仅存本机</span></div><form id="profileForm"><div class="profile-fields"><label for="heightCm">身高 <span>厘米</span><input id="heightCm" name="heightCm" type="number" inputmode="decimal" min="100" max="230" step="0.1" value="${p.heightCm??''}" placeholder="选填"></label><label for="weightKg">体重 <span>千克</span><input id="weightKg" name="weightKg" type="number" inputmode="decimal" min="25" max="350" step="0.1" value="${p.weightKg??''}" placeholder="选填"></label><label for="ageYears">年龄 <span>周岁</span><input id="ageYears" name="ageYears" type="number" inputmode="numeric" min="1" max="110" step="1" value="${p.ageYears??''}" placeholder="选填"></label><label for="measuredAt">测量日期<input id="measuredAt" name="measuredAt" type="date" max="${today}" value="${p.measuredAt??today}"></label><label for="activity">活动水平<select id="activity" name="activity">${options(activityLabels,p.activity??'light')}</select></label><label for="dietGoal">饮食目标<select id="dietGoal" name="goal">${options(goalLabels,p.goal??'balanced')}</select></label></div><label class="check-row"><input type="checkbox" name="generalAdult" ${p.generalAdult?'checked':''}>我属于18–64岁一般成人，不处于孕哺期，也没有需要遵医嘱的特殊饮食要求</label><label class="check-row"><input type="checkbox" name="enabled" ${p.enabled?'checked':''}>启用饮食搭配建议，仅影响合格候选的排序</label><p class="small muted">其他人群仍可正常逛菜单、抽餐与记饭本，仅显示通用搭配信息。不生成疾病忌口或每日热量处方。</p><div id="profileError" role="alert"></div><div class="profile-actions"><button type="submit" class="button primary">保存身体资料</button><button type="button" class="button secondary" data-action="reload-profile" hidden>载入最新饭本</button><button type="button" class="text-button" data-action="clear-profile" ${!state.profile?'disabled':''}>清除身体资料</button></div></form>${bmi?`<div class="bmi-reference"><div><strong>${bmi.value}</strong><span>BMI体重参考</span></div><p>${esc(bmi.label)}。${esc(bmi.note)}<a href="${bmi.source}" target="_blank" rel="noopener noreferrer">查看依据</a></p></div>`:''}${generalDietNote()}</section>`;}
export function assistantMarkup(state,records,eligible){
 const active=canPersonalize(state.profile),ranked=eligible.map(d=>({d,...dietAssessment(d,state,records)})).sort((a,b)=>b.score-a.score).slice(0,3),actual=(state.history??[]).length;
 return `<section class="diet-assistant"><div class="section-head"><div><p class="kicker">让一餐搭配更完整</p><h2>今日饮食参考</h2></div><span class="local-badge">${active?'按你的目标参考':'通用搭配'}</span></div>${!active?'<p>优先保留主食，搭配蔬菜与蛋、奶、肉或豆制品。填写资料后，可开启有解释的搭配排序。</p>':`<p>当前目标：${esc(goalLabels[state.profile.goal])}。建议只参考你确认吃过的记录；目前饭本有${actual}条实际用餐记录，不代表完整摄入。</p>`}<div class="assistant-columns"><div><h3>今日优先考虑</h3>${ranked.length?ranked.map(({d,notes})=>`<button class="assistant-pick" data-action="detail" data-id="${d.id}"><strong>${esc(d.name)}</strong><span>${esc(notes[0]??'包含主食的选餐灵感，按实际份量搭配')}</span>${icon('arrow')}</button>`).join(''):'<p>当前筛选没有主餐候选，可先调整选餐条件。</p>'}</div><div class="assistant-guidance"><h3>建议少选</h3><p>少把单粥、小食或沙拉直接当作完整正餐；避免连续只选同类油炸食物。</p><h3>这样搭配更完整</h3><p>主食照常保留，蔬菜多换种类；按实际份量补充蛋、奶或豆类。没有完整配方时，向窗口确认。</p></div></div><button class="text-button" data-action="open-profile">${state.profile?'调整资料与开关':'填写参考资料'} ${icon('arrow')}</button>${generalDietNote()}</section>`;
}
